package com.hms.website;
import com.hms.tenancy.*; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/hospitals/{tenantSlug}/website/theme-snapshots") public class WebsiteThemeSnapshotController {private final TenantRepository tenants;private final WebsiteSettingsRepository settings;private final WebsiteThemeSnapshotRepository snapshots;public WebsiteThemeSnapshotController(TenantRepository t,WebsiteSettingsRepository s,WebsiteThemeSnapshotRepository p){tenants=t;settings=s;snapshots=p;} @GetMapping public List<WebsiteThemeSnapshot> list(@PathVariable String tenantSlug){return snapshots.findAllByTenantIdOrderByCreatedAtDesc(tenant(tenantSlug));} @PostMapping public WebsiteThemeSnapshot create(@PathVariable String tenantSlug){UUID t=tenant(tenantSlug);WebsiteSettings current=settings.findByTenantId(t).orElseThrow(()->new IllegalArgumentException("Website settings not configured"));return snapshots.save(new WebsiteThemeSnapshot(t,current));} @PostMapping("/{snapshotId}/restore") public WebsiteSettings restore(@PathVariable String tenantSlug,@PathVariable UUID snapshotId){UUID t=tenant(tenantSlug);WebsiteThemeSnapshot snapshot=snapshots.findByIdAndTenantId(snapshotId,t).orElseThrow(()->new IllegalArgumentException("Theme snapshot not found"));WebsiteSettings current=settings.findByTenantId(t).orElseThrow(()->new IllegalArgumentException("Website settings not configured"));current.apply(snapshot.request());return settings.save(current);} private UUID tenant(String slug){return tenants.findBySlug(slug).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(slug));}}
